using FluentValidation; using MediatR; using Microsoft.EntityFrameworkCore; using InventorySystem.Application.Interfaces; using InventorySystem.Domain.Entities;
namespace InventorySystem.Application.Features.Stock.Commands;
public record AddStockCommand(int ProductId,int WarehouseId,int Quantity,MovementType Type,string? Reference,string? Notes,int? DestinationWarehouseId=null) : IRequest<int>;
public class AddStockCommandValidator : AbstractValidator<AddStockCommand> { public AddStockCommandValidator(){ RuleFor(x=>x.ProductId).GreaterThan(0); RuleFor(x=>x.WarehouseId).GreaterThan(0); RuleFor(x=>x.Quantity).GreaterThan(0); RuleFor(x=>x.Type).IsInEnum(); RuleFor(x=>x.DestinationWarehouseId).NotNull().GreaterThan(0).When(x=>x.Type==MovementType.TransferOut).WithMessage("DestinationWarehouseId is required for transfers."); RuleFor(x=>x).Must(x=>x.DestinationWarehouseId!=x.WarehouseId).When(x=>x.Type==MovementType.TransferOut&&x.DestinationWarehouseId.HasValue).WithMessage("Destination warehouse must differ from the source warehouse."); } }
public class AddStockCommandHandler(IAppDbContext db) : IRequestHandler<AddStockCommand,int> { public async Task<int> Handle(AddStockCommand r,CancellationToken ct){ var p=await db.Products.FindAsync([r.ProductId],ct)??throw new KeyNotFoundException("Product not found."); _=p; _=await db.Warehouses.FindAsync([r.WarehouseId],ct)??throw new KeyNotFoundException("Warehouse not found."); var srcItem=await GetOrCreateItem(r.ProductId,r.WarehouseId,ct); var isOut=r.Type is MovementType.SaleOut or MovementType.TransferOut; if(srcItem.Quantity+(isOut?-r.Quantity:r.Quantity)<0) throw new InvalidOperationException("Stock cannot be negative."); srcItem.Quantity+=isOut?-r.Quantity:r.Quantity; var srcMove=new StockMovement{ProductId=r.ProductId,WarehouseId=r.WarehouseId,Quantity=r.Quantity,Type=r.Type,Reference=r.Reference,Notes=r.Notes}; db.StockMovements.Add(srcMove); if(r.Type==MovementType.TransferOut&&r.DestinationWarehouseId.HasValue){ _=await db.Warehouses.FindAsync([r.DestinationWarehouseId.Value],ct)??throw new KeyNotFoundException("Destination warehouse not found."); var destItem=await GetOrCreateItem(r.ProductId,r.DestinationWarehouseId.Value,ct); destItem.Quantity+=r.Quantity; db.StockMovements.Add(new StockMovement{ProductId=r.ProductId,WarehouseId=r.DestinationWarehouseId.Value,Quantity=r.Quantity,Type=MovementType.TransferIn,Reference=r.Reference,Notes=r.Notes}); } await db.SaveChangesAsync(ct); return srcMove.Id; } private async Task<StockItem> GetOrCreateItem(int productId,int warehouseId,CancellationToken ct){ var item=await db.StockItems.FirstOrDefaultAsync(x=>x.ProductId==productId&&x.WarehouseId==warehouseId&&!x.IsDeleted,ct); if(item is null){ item=new StockItem{ProductId=productId,WarehouseId=warehouseId,Quantity=0}; db.StockItems.Add(item); } return item; } }
